if not doc.custom_application_access and doc.user_id:
    user_to_delete = doc.user_id

    if user_to_delete not in ("Administrator", "Guest"):
        doc.user_id = None

        if frappe.db.exists("User", user_to_delete):
            frappe.delete_doc(
                "User", user_to_delete, ignore_permissions=True, force=True
            )

            frappe.msgprint(
                msg=f"User account <b>{user_to_delete}</b> has been successfully deleted.",
                title="User Removed",
                indicator="orange",
                alert=True,
            )

elif doc.custom_application_access:
    # Auto-enable ERPNext's own "Create User Permission" checkbox whenever Application
    # Access is on, so the employee's linked User automatically gets restricted to this
    # Employee's Company via core Employee.update_user_permissions() -- no separate manual
    # tick needed. Only ever turned ON here, never OFF, so an admin who explicitly
    # unchecks it later (e.g. to grant broader access) isn't overridden on next save.
    if not doc.create_user_permission:
        doc.create_user_permission = 1

if doc.user_id and doc.user_id not in ("Administrator", "Guest"):
    user_to_delete = doc.user_id

    if frappe.db.exists("User", user_to_delete):
        frappe.delete_doc(
            "User", user_to_delete, ignore_permissions=True, force=True
        )

        frappe.msgprint(
            msg=f"User account <b>{user_to_delete}</b> has been deleted along with this Employee record.",
            title="User Removed",
            indicator="orange",
            alert=True,
        )
